var d = System.AppDomain.CurrentDomain;
var sc = UnityEngine.SceneManagement.SceneManager.GetActiveScene().name;
var camp = LevelSelectionController.currentCampaign;
string key = sc + "|" + (camp == null ? "" : camp.name) + "|" + LevelSelectionController.CurrentLevelNum;
var ic = System.Globalization.CultureInfo.InvariantCulture;
float now = UnityEngine.Time.realtimeSinceStartup;
var last = d.GetData("uimtest.settle") as string;
int cut = last == null ? -1 : last.LastIndexOf('|');
if (last == null || last.Substring(0, cut) != key) {
  d.SetData("uimtest.settle", key + "|" + now.ToString(ic));
  return "waiting: " + sc + " just came up";
}
float since = now - float.Parse(last.Substring(cut + 1), ic);
if (sc == "LoadingScreen") return "waiting: loading";
if (LevelSelectionController.IsCampaignScene) {
  if (HeroController.Instance == null || Map.Instance == null || GameModeController.Instance == null) return "waiting: the level is still being built";
  var wt = typeof(GameModeController).GetField("winTimer", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
  if (GameModeController.IsLevelFinished() && (float)wt.GetValue(GameModeController.Instance) < 999999f) return "waiting: the level finished and is moving on";
}
if (since < 4f) return "waiting: " + sc + " unchanged for " + since.ToString("0.0", ic) + " s";
return "settled in " + sc;

var d = System.AppDomain.CurrentDomain;
string lv = "0|1";
if (LevelSelectionController.IsCampaignScene && LevelSelectionController.currentCampaign != null) {
  var all = typeof(Unity_Inspector_Mod.StateModifier).GetField("CampaignNames", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static).GetValue(null) as string[];
  for (int i = 0; i < all.Length; i++) if (string.Equals(all[i], LevelSelectionController.currentCampaign.name, System.StringComparison.OrdinalIgnoreCase)) lv = i + "|" + LevelSelectionController.CurrentLevelNum;
}
d.SetData("uimtest.level", lv);
d.SetData("uimtest.settle", null);
return "recorded level=" + lv;

var d = System.AppDomain.CurrentDomain;
var save = GameState.Instance == null ? null : GameState.Instance.currentWorldmapSave;
var wp = save == null ? null : save.currentWorldMapProgress;
var tp = wp == null || string.IsNullOrEmpty(wp.currentTerritoryName) ? null : wp.GetTerritoryProgress(wp.currentTerritoryName);
d.SetData("uimtest.lr.startlevel", tp == null ? null : wp.currentTerritoryName + "|" + tp.startLevel);
var pp = PlayerProgress.Instance;
d.SetData("uimtest.lr.progress", pp == null ? null : pp.freedBros + "|" + System.Linq.Enumerable.Count(System.Linq.Enumerable.Union(pp.unlockedHeroes, pp.yetToBePlayedUnlockedHeroes)));
return "start level " + (tp == null ? "unrecorded" : wp.currentTerritoryName + " " + tp.startLevel) + ", progress " + (pp == null ? "unrecorded" : pp.freedBros + " freed, " + System.Linq.Enumerable.Count(System.Linq.Enumerable.Union(pp.unlockedHeroes, pp.yetToBePlayedUnlockedHeroes)) + " bros unlocked");

var d = System.AppDomain.CurrentDomain;
var sl = d.GetData("uimtest.lr.startlevel") as string;
d.SetData("uimtest.lr.startlevel", null);
string held;
if (ScenarioLevelRun.Outcome != "finished") held = "outcome " + ScenarioLevelRun.Outcome + ", no finish to hold";
else {
  var g = GameModeController.Instance;
  var bf = System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance;
  bool finished = GameModeController.IsLevelFinished();
  bool switching = g != null && (bool)typeof(GameModeController).GetField("switchingLevel", bf).GetValue(g);
  float timer = g == null ? -1f : (float)typeof(GameModeController).GetField("winTimer", bf).GetValue(g);
  held = finished && !switching && timer > 1000f ? "outcome held" : "outcome ran: levelFinished=" + finished + ", switchingLevel=" + switching + ", winTimer=" + timer;
}
string start;
if (sl == null) start = "startLevel unrecorded";
else {
  var sp = sl.Split('|');
  var save = GameState.Instance.currentWorldmapSave;
  var tp = save == null || save.currentWorldMapProgress == null ? null : save.currentWorldMapProgress.GetTerritoryProgress(sp[0]);
  start = tp == null ? "startLevel unreadable" : tp.startLevel.ToString() == sp[1] ? "startLevel kept" : "startLevel changed from " + sp[1] + " to " + tp.startLevel;
}
var pr = d.GetData("uimtest.lr.progress") as string;
d.SetData("uimtest.lr.progress", null);
var pq = PlayerProgress.Instance;
string now = pq == null ? null : pq.freedBros + "|" + System.Linq.Enumerable.Count(System.Linq.Enumerable.Union(pq.unlockedHeroes, pq.yetToBePlayedUnlockedHeroes));
string progress = pr == null || now == null ? "progress unrecorded" : pr == now ? "progress kept" : "progress changed: freed|unlocked from " + pr + " to " + now;
return held + "; " + start + "; " + progress;

var d = System.AppDomain.CurrentDomain;
var rec = (d.GetData("uimtest.level") as string) ?? "0|1";
d.SetData("uimtest.level", null);
var p = rec.Split('|');
var r = Unity_Inspector_Mod.StateModifier.GoToLevel(int.Parse(p[0]), int.Parse(p[1]));
var j = Newtonsoft.Json.Linq.JToken.FromObject(r);
return "loading recorded level " + rec + ": success=" + j["success"] + " " + j.ToString(Newtonsoft.Json.Formatting.None);

var d = System.AppDomain.CurrentDomain;
var rec = d.GetData("uimtest.level") as string;
d.SetData("uimtest.level", null);
if (rec == null) return "no level recorded";
var p = rec.Split('|');
var r = Unity_Inspector_Mod.StateModifier.GoToLevel(int.Parse(p[0]), int.Parse(p[1]));
var j = Newtonsoft.Json.Linq.JToken.FromObject(r);
return "loading recorded level " + rec + ": success=" + j["success"] + " " + j.ToString(Newtonsoft.Json.Formatting.None);
